PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX VideoGameOntology: <http://example.org/VideoGameOntology#>

SELECT ?player
WHERE {
  ?player VideoGameOntology:hasAchievement VideoGameOntology:Loyalty .
  {
    SELECT ?player (COUNT(?gainEvent) AS ?gainEventCount)
    WHERE {
      ?player VideoGameOntology:hasGainEvent ?gainEvent .
    }
    GROUP BY ?player
    ORDER BY DESC(?gainEventCount)
    LIMIT 1
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX VideoGameOntology: <http://example.com/VideoGameOntology#>

SELECT ?eventType
WHERE {
  ?eventType rdfs:subClassOf* VideoGameOntology:InstantaneousEvent .
  ?eventType rdfs:subClassOf [ 
    a owl:Restriction ;
    owl:onProperty VideoGameOntology:isEventInSession ;
    owl:someValuesFrom VideoGameOntology:Session
  ] .
}

