PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX VideoGameOntology: <http://example.org/VideoGameOntology#>

SELECT ?event ?achievement
WHERE {
  { 
    ?event rdf:type VideoGameOntology:InAppPurchaseEvent ;
           VideoGameOntology:unlocksAchievement ?achievement .
  }
  UNION
  { 
    ?event rdf:type VideoGameOntology:MenuEvent ;
           VideoGameOntology:unlocksAchievement ?achievement .
  }
  ?event VideoGameOntology:isEventInSession ?session .
}
ORDER BY ?session

