SELECT (COUNT(DISTINCT ?gameWithEventRelatedItem) / COUNT(DISTINCT ?game) AS ?percentage)
WHERE {
  ?game rdf:type VideoGameOntology:Game .
  OPTIONAL {
    ?item VideoGameOntology:isItemInGame ?game ;
          VideoGameOntology:isEventRelatedToItem ?event .
    BIND(?game AS ?gameWithEventRelatedItem)
  }
}

