PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?player (SUM(?duration) AS ?totalDuration)
WHERE {
  ?player VideoGameOntology:username ?username .
  ?session VideoGameOntology:startTime ?startTime ;
           VideoGameOntology:endTime ?endTime ;
           VideoGameOntology:username ?username .
  BIND(xsd:dateTime(?endTime) - xsd:dateTime(?startTime) AS ?duration)
}
GROUP BY ?player

