SELECT ?person (COUNT(?game) AS ?numberOfGames)
WHERE {
  ?game rdf:type owl:NamedIndividual .
  {
    ?game dc:creator ?person
  } UNION {
    ?game dc:contributor ?person
  }
}
GROUP BY ?person
